 const[devices,setDevices]=React.useState<Devices>(demoDevices);const[input,setInput]=React.useState(()=>localStorage.getItem('flaw-input')||'demo-in');const[output,setOutput]=React.useState(()=>localStorage.getItem('flaw-output')||'demo-out');
 const[running,setRunning]=React.useState(false);const[native,setNative]=React.useState(false);const[busy,setBusy]=React.useState(false);const[status,setStatus]=React.useState('Native audio engine disconnected');
 const[metrics,setMetrics]=React.useState<Metrics>(zeroMetrics);const[visual,setVisual]=React.useState<VisualFrame>({waveform:Array(256).fill(0),bands:Array(32).fill(0)});
 const[showIntro,setShowIntro]=React.useState(true);const[bypass,setBypass]=React.useState(()=>localStorage.getItem('flaw-bypass')==='true');
 const[quality,setQuality]=React.useState<'Eco'|'Balanced'|'Ultra'>(()=>(localStorage.getItem('flaw-quality') as 'Eco'|'Balanced'|'Ultra')||'Balanced');
 const[compact,setCompact]=React.useState(()=>localStorage.getItem('flaw-compact')==='true');const[calibrating,setCalibrating]=React.useState(false);
 const[customPresets,setCustomPresets]=React.useState<SavedPreset[]>(()=>{try{return JSON.parse(localStorage.getItem('flaw-presets')||'[]')}catch{return[]}});
 const[fileRef]=React.useState(()=>React.createRef<HTMLInputElement>());const[toast,setToast]=React.useState('');
 const[ceiling,setCeiling]=React.useState(()=>Number(localStorage.getItem('flaw-ceiling')||'-0.8'));
 const[platformBootstrap,setPlatformBootstrap]=React.useState<PlatformBootstrap>({has_owner:false,local_backend:true,app_version:APP_VERSION});
 const[platformSession,setPlatformSession]=React.useState<PlatformSession|null>(null);const[platformReady,setPlatformReady]=React.useState(false);const[platformBusy,setPlatformBusy]=React.useState(false);const[platformError,setPlatformError]=React.useState('');
 const[announcementFeed,setAnnouncementFeed]=React.useState<AnnouncementFeed>({unread_count:0,unread_ids:[],items:[]});const[announcementOpen,setAnnouncementOpen]=React.useState(false);
 const[reportOpen,setReportOpen]=React.useState(false);const[reportBusy,setReportBusy]=React.useState(false);const[adminSnapshot,setAdminSnapshot]=React.useState<AdminSnapshot|null>(null);
 const[externalEqMode,setExternalEqMode]=React.useState(()=>localStorage.getItem('flaw-external-eq-mode')==='true');const[externalEqHeadroom,setExternalEqHeadroom]=React.useState(()=>Number(localStorage.getItem('flaw-external-eq-headroom')||'10'));
 const[onboardingStep,setOnboardingStep]=React.useState(()=>localStorage.getItem('flaw-onboarded-v09')?'': '0');
 const[diagnostics,setDiagnostics]=React.useState<SystemDiagnostics|null>(null);const[updateStatus,setUpdateStatus]=React.useState<UpdateStatus|null>(null);
 const[recoveryNotice,setRecoveryNotice]=React.useState(()=>localStorage.getItem('flaw-session-dirty')==='true');const[hotkeysReady,setHotkeysReady]=React.useState(false);
 const[ambientFx,setAmbientFx]=React.useState(()=>localStorage.getItem('flaw-ambient-fx')==='true');
