 const[motionLevel,setMotionLevel]=React.useState<MotionLevel>(()=>(localStorage.getItem('flaw-motion-level') as MotionLevel)||'Normal');
 const[reduceMotion,setReduceMotion]=React.useState(()=>localStorage.getItem('flaw-reduce-motion')==='true');
 const[lockControls,setLockControls]=React.useState(()=>localStorage.getItem('flaw-lock-controls')==='true');
 const[focusMode,setFocusMode]=React.useState(false);
 const[latencyTarget,setLatencyTarget]=React.useState<'Lowest'|'Balanced'|'Safe'>(()=>(localStorage.getItem('flaw-latency-target') as any)||'Balanced');
 const[commandOpen,setCommandOpen]=React.useState(false);const[commandQuery,setCommandQuery]=React.useState('');
 const[favorites,setFavorites]=React.useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem('flaw-favorites')||'[]')}catch{return[]}});
 const[recentPresets,setRecentPresets]=React.useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem('flaw-recent-presets')||'[]')}catch{return[]}});
 const[scenes,setScenes]=React.useState<Scene[]>(()=>{try{return JSON.parse(localStorage.getItem('flaw-scenes')||'[]')}catch{return[]}});
 const[timeline,setTimeline]=React.useState<TimelineEvent[]>(()=>[]);
 const[enginePhase,setEnginePhase]=React.useState<'Idle'|'Arming'|'Routing'|'DSP Online'|'CleanGuard Ready'>('Idle');
 const[micTestUrl,setMicTestUrl]=React.useState('');const[micTesting,setMicTesting]=React.useState(false);
 const[performanceHud,setPerformanceHud]=React.useState(()=>localStorage.getItem('flaw-performance-hud')==='true');
 const[qaMode,setQaMode]=React.useState(()=>localStorage.getItem('flaw-qa-mode')==='true');
 const[safeBootActive,setSafeBootActive]=React.useState(()=>localStorage.getItem('flaw-session-dirty')==='true');
 const[streamMode,setStreamMode]=React.useState(()=>localStorage.getItem('flaw-stream-mode')!=='false');
 const[streamHotkey,setStreamHotkey]=React.useState(()=>localStorage.getItem('flaw-stream-hotkey')||'PageUp');
 const[recordingHotkey,setRecordingHotkey]=React.useState(false);
 const[unloadHotkey,setUnloadHotkey]=React.useState(()=>{const saved=localStorage.getItem('flaw-unload-hotkey');return !saved||saved==='NumpadDecimal'?'Delete':saved});
 const[recordingUnloadHotkey,setRecordingUnloadHotkey]=React.useState(false);
 const[fxDensity,setFxDensity]=React.useState(()=>Number(localStorage.getItem('flaw-fx-density')||'0.55'));
