 const[updateCheck,setUpdateCheck]=React.useState<UpdateCheck|null>(null);
 const toastMsg=(s:string)=>{setToast(s);setTimeout(()=>setToast(''),2400)};
 const refreshDevices=React.useCallback(async(preserve=true)=>{try{const d=await invoke<Devices>('list_audio_devices');setNative(true);setDevices(d);const di=preserve?d.inputs.find(x=>x.id===input):undefined;const doKeep=preserve?d.outputs.find(x=>x.id===output):undefined;const defaultIn=di??d.inputs.find(x=>x.is_default)??d.inputs[0];const defaultOut=doKeep??d.outputs.find(x=>x.name.toLowerCase().includes('cable input'))??d.outputs.find(x=>x.is_default)??d.outputs[0];if(defaultIn)setInput(defaultIn.id);if(defaultOut)setOutput(defaultOut.id);setStatus(d.inputs.length&&d.outputs.length?'Audio devices ready':'No compatible audio devices found');return d;}catch{setNative(false);setStatus('UI Preview · run with npm run tauri dev for native audio');return null}},[input,output]);
